"""Shared stator-fastened race cap with an independent axial race-clearance stop."""
class DfmaSharedRollCapIntent(PairedHousingIntent):
 def proposal_parameters(self):
  self.housing_parameters();g=self.g
  for key,value in {'dfma_roll_cap_thickness':3,'dfma_roll_cap_radius':40.5,'dfma_roll_capture_gap':.15,'dfma_roll_rear_radial_clearance':.5,'dfma_roll_cap_screw_nominal_diameter':3,'dfma_roll_cap_screw_diametral_clearance':.8,'dfma_roll_stator_screw_length':35}.items():
   g.parameter(key,value,comment='Isolated DFMA shared-cap proposal. Common M3 screw specification; race clearance and printed preload remain fit-unqualified.')
  for key,value in {'dfma_roll_cap_head_seat_x':'pr_bearing_end_x+dfma_roll_cap_thickness','dfma_roll_stator_screw_tip_x':'dfma_roll_cap_head_seat_x-dfma_roll_stator_screw_length','dfma_roll_stator_modeled_engagement':'pr_housing_back_x-dfma_roll_stator_screw_tip_x','dfma_roll_rear_relief_radius':'pr_bearing_od/2+dfma_roll_rear_radial_clearance','dfma_roll_cap_screw_radius':'(dfma_roll_cap_screw_nominal_diameter+dfma_roll_cap_screw_diametral_clearance)/2'}.items():g.parameter(key,value)
 def cap(self):
  self.proposal_parameters();g=self.g;c=self.c;turn=CohesiveCarrierIntent(g)
  body=turn.revolve([('pr_bearing_end_x','dfma_roll_rear_relief_radius'),('pr_bearing_end_x','dfma_roll_cap_radius'),('dfma_roll_cap_head_seat_x','dfma_roll_cap_radius'),('dfma_roll_cap_head_seat_x','pr_outer_open_radius'),('pr_bearing_end_x+dfma_roll_capture_gap','pr_outer_open_radius'),('pr_bearing_end_x+dfma_roll_capture_gap','dfma_roll_rear_relief_radius')],c.xConstructionAxis,'Continuous cap with separate race-clearance stop')
  return self.patterned_circle(body,'pr_bearing_end_x-1 mm','dfma_roll_cap_thickness+2 mm','dfma_roll_cap_screw_radius','pr_stator_pcd_radius',0,9,'Nine shared motor-stator screw passages')
 def cartridge(self):
  self.proposal_parameters();g=self.g;c=self.c;body=self.annulus('pr_housing_split_x','pr_bearing_end_x-pr_housing_split_x','pr_housing_radius','pr_seat_radius','Uninterrupted through-bored bearing barrel');body=self.patterned_circle(body,'pr_housing_split_x','pr_bearing_end_x-pr_housing_split_x','ph_column_radius','pr_stator_pcd_radius',0,9,'Nine shared stator clamp columns',True);ears=[];limb=CohesiveLimbIntent(g)
  for z,label in [('ph_lower_ear_z','Lower'),('ph_upper_ear_z','Upper')]:
   ear=g.box('ph_ear_width','ph_ear_depth','ph_ear_height','ph_ear_x','ph_ear_y',z,label+' unchanged chassis attachment ear');ear=g.round_edges(ear,'ph_ear_round',label+' ear edge radii');sk=limb.circles('7 mm',[('ph_ear_x',z,'ph_ear_hole_radius')],label+' straight chassis screw passage');ear=limb.extrude_all(sk,'30 mm',label+' straight chassis screw passage',fusion.FeatureOperations.CutFeatureOperation,ear);ears.append(ear)
  body=g.combine(body,ears,fusion.FeatureOperations.JoinFeatureOperation,'Integral chassis ears without separate retainer pillars');sk=self.circles('pr_housing_split_x-1 mm',[('0 mm','0 mm','pr_seat_radius')],'Uninterrupted bearing extraction bore');body=g.extrude(sk,'pr_bearing_end_x-pr_housing_split_x+2 mm','Preserve full-width seats through attachment roots',fusion.FeatureOperations.CutFeatureOperation,[body]).bodies.item(0);return self.patterned_circle(body,'pr_housing_split_x-1 mm','pr_bearing_end_x-pr_housing_split_x+2 mm','ph_stator_hole_radius','pr_stator_pcd_radius',0,9,'Nine unchanged motor-stator screw passages')
 def backplate(self):
  self.proposal_parameters();g=self.g;body=self.annulus('pr_housing_back_x','pr_stator_plate_thickness','pr_stator_plate_radius','ph_stator_plate_bore_radius','Removable stator plate without obsolete nut pockets');collar=self.annulus('pr_housing_split_x','pr_bearing_rear_x-pr_housing_split_x','pr_bearing_od/2','pr_outer_open_radius','Rear outer-race stop and extraction collar');body=g.combine(body,[collar],fusion.FeatureOperations.JoinFeatureOperation,'Integral supported rear race collar');return self.patterned_circle(body,'pr_housing_back_x-1 mm','pr_stator_plate_thickness+2 mm','ph_stator_hole_radius','pr_stator_pcd_radius',0,9,'Nine ordinary motor-stator screw passages')
